ground_truth_sql:
SELECT "nct", "author", "year", "publication_type", "ici_class", "cancer_type", "trial_phase"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Mesothelioma' AND "ici_class" = 'PD1' AND NULLIF(regexp_replace(("year")::text, '[^0-9\.-]', '', 'g'), '')::numeric >= 2018;

gt_sql_final:
SELECT "nct", "author", "year", "originial_publication_or_follow_up", "class_of_ici", "cancer_type", "trial_phase"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Mesothelioma' AND "class_of_ici" = 'PD1' AND NULLIF(regexp_replace(("year")::text, '[^0-9\.-]', '', 'g'), '')::numeric >= 2018;
